@startuml

class Location {
  + address : string
}

class Driver {
  + firstName : string
  + lastName : string
}

class Vehicle {
  + vehicleNumber : string
}

abstract class Truck {
  + weight : float
}

abstract class Car {
  + numberOfSeats : int
}

abstract class Van {}

class Order {
  + originLocation : string
  + destinationLocation : string
  + executionDate : date
}

Truck --|> Vehicle
Car --|> Vehicle
Van --|> Vehicle

Location "1" -- "*" Driver
Location "1" -- "*" Vehicle
Location "1" -- "*" Order : origin
Location "1" -- "*" Order : destination

Driver "1" -- "0..1" Order : carries
Driver "1" -- "0..1" Vehicle : drives

@enduml

